input.sparql:
SELECT ?sensor ?ts_id WHERE {
  ?zone rdfs:label "Perimeter_bot_ZN_3" .
  ?sensor brick:location ?zone ;
          rdf:type brick:TemperatureSensor .
  ?sensor ref:hasExternalReference ?ts_id .
}

SELECT ?point ?ts_id WHERE {
  ?zone rdfs:label "Perimeter_bot_ZN_3" .
  { ?point brick:location ?zone } UNION { ?point brick:isPointOf ?zone } .
  ?point ref:hasExternalReference ?ts_id .
}
